// ---------- SEO console ----------
function serp(title,url,desc){return `<div class="serp" aria-hidden="true"><cite>${esc(url)}</cite><b>${esc(title)}</b><span>${esc(desc)}</span></div>`}
function counted(key,title,value,placeholder,max,multi=false){return `<label for="${key}">${esc(title)} <span class="cnt" data-count-for="${key}" data-max="${max}">${(value||'').length} / ${max}</span></label>${multi?`<textarea id="${key}" name="${key}" rows="3" placeholder="${esc(placeholder||'')}" data-count>${esc(value||'')}</textarea>`:`<input id="${key}" name="${key}" value="${esc(value||'')}" placeholder="${esc(placeholder||'')}" data-count>`}`}
async function seoTab(e){seoData=await api('/admin/seo');const x=seoData,c=x.config,job=x.job||{},base=x.sitemap.replace(/\/sitemap\.xml$/,'');
 const suits=[['major','大阿卡纳','Major Arcana'],['wands','权杖','Wands'],['cups','圣杯','Cups'],['swords','宝剑','Swords'],['pentacles','星币','Pentacles']];
 e.innerHTML=`<div class="note">${t('这里管理搜索引擎看到的内容：每个页面的标题和描述、78 张牌的独立牌义页、验证码和主动推送。改动保存后，Bing / Yandex 会通过 IndexNow 立刻收到通知；Google 通过站点地图自动发现。','Manage what search engines see: page titles and descriptions, the 78 card pages, verification codes and instant pings. Saved changes are pushed to Bing / Yandex via IndexNow; Google discovers them from the sitemap.')}</div>
 <section class="panel"><h2 class="h3">${t('体检结果','Health check')}</h2>${x.checks.length?`<ul class="checks">${x.checks.map(k=>`<li class="${k.level}">${esc(t(k.zh,k.en))}</li>`).join('')}</ul>`:`<p>${t('没有发现问题。','No issues found.')}</p>`}</section>
 <div class="dash-grid"><section class="panel"><h2 class="h3">${t('收录与推送','Indexing')}</h2><p>${t('站点地图','Sitemap')}：<a href="${esc(x.sitemap)}" target="_blank" rel="noopener">${esc(x.sitemap)}</a> · ${t('共','')} ${fmt(x.url_count)} ${t('个网址','URLs')}</p><p>IndexNow ${t('密钥文件','key file')}：<a href="${esc(x.indexnow_url)}" target="_blank" rel="noopener">${esc(x.indexnow_url)}</a></p><div class="actions"><button type="button" data-admin="indexnow">${t('把全部网址推送给 Bing / Yandex','Push all URLs to Bing / Yandex')}</button><a class="button" href="https://search.google.com/search-console" target="_blank" rel="noopener">Google Search Console ↗</a><a class="button" href="https://www.bing.com/webmasters" target="_blank" rel="noopener">Bing Webmaster ↗</a></div>${x.log.length?`<details><summary>${t('最近推送记录','Recent pushes')}</summary><table class="data-table"><tbody>${x.log.slice(0,10).map(l=>`<tr><td>${esc((l.at||'').slice(0,16).replace('T',' '))}</td><td>${esc(l.kind)} · ${esc(l.reason||'')}</td><td>${fmt(l.count)}</td><td>${l.ok?'✓':'✗ '+esc(String(l.status||l.error||''))}</td></tr>`).join('')}</tbody></table></details>`:''}</section>
 <section class="panel"><h2 class="h3">${t('验证与分享图','Verification & share image')}</h2><form data-admin-form="seo-config"><p class="muted small">${t('可直接粘贴平台给的整段 &lt;meta&gt; 标签，系统只保留验证码。','Paste the whole &lt;meta&gt; tag if you like; only the code is kept.')}</p>${field('v_google','Google (google-site-verification)',c.verify.google||'')}${field('v_bing','Bing (msvalidate.01)',c.verify.bing||'')}${field('v_baidu',t('百度 (baidu-site-verification)','Baidu'),c.verify.baidu||'')}${field('v_yandex','Yandex',c.verify.yandex||'')}${field('og_image',t('分享卡片图片 HTTPS 地址（留空用默认，1200×630）','Share image HTTPS URL (blank = default, 1200×630)'),c.og_image||'')}${check('indexnow',t('页面有更新时自动推送 IndexNow','Ping IndexNow automatically when pages change'),c.indexnow)}<button class="primary">${t('保存','Save')}</button></form></section></div>
 <h2 class="section-head">${t('页面标题与描述','Page titles & descriptions')}</h2><p class="muted">${t('留空即使用系统默认值。下方预览是搜索结果里大致的样子。','Leave blank to use the default. The preview shows roughly how it looks in search results.')}</p>
 ${x.pages.map(p=>`<details class="panel seo-page"><summary><b>${esc(p.path)}</b> <span class="muted">${esc(p.zh_title)}</span>${Object.keys(p.override).length?` <span class="badge">${t('已自定义','Custom')}</span>`:''}</summary><div class="two"><div>${serp(p.zh_title,base+p.path,p.zh_desc)}</div><div>${serp(p.en_title,base+p.path+'?lang=en',p.en_desc)}</div></div><form data-admin-form="seo-page" data-key="${esc(p.key)}"><div class="two"><div>${counted(p.key+'_zh_title',t('中文标题','Chinese title'),p.override.zh_title,p.default_zh_title,32)}${counted(p.key+'_zh_desc',t('中文描述','Chinese description'),p.override.zh_desc,p.default_zh_desc,120,true)}</div><div>${counted(p.key+'_en_title',t('英文标题','English title'),p.override.en_title,p.default_en_title,65)}${counted(p.key+'_en_desc',t('英文描述','English description'),p.override.en_desc,p.default_en_desc,160,true)}</div></div><button class="primary">${t('保存','Save')}</button></form></details>`).join('')}
 <h2 class="section-head">${t('78 张牌义页','The 78 card pages')}</h2>
 <div class="panel"><p>${t('每张牌都有独立网址（如','Each card has its own URL (e.g. ')}<a href="/learn/the-fool" target="_blank" rel="noopener">/learn/the-fool</a>${t('），是塔罗网站最主要的自然搜索入口。只有关键词的页面内容偏少；可以让 AI 写一段原创介绍（中英文），再由你审核修改。英文页在有英文介绍后才开放收录。',') — the main way tarot sites are found in search. Keyword-only pages are thin: let the AI draft an original introduction (Chinese and English) and review it. English pages open to indexing once they have English copy.')}</p>
 <p><b>${t('进度','Progress')}</b>：${t('中文介绍','Chinese')} ${x.cards.filter(k=>k.has_zh).length}/78 · ${t('英文介绍','English')} ${x.cards.filter(k=>k.has_en).length}/78 · ${t('AI 生成待审核','AI drafts to review')} ${x.cards.filter(k=>k.ai).length}</p>
 ${job.running?`<p class="note">${t('批量生成进行中','Batch running')}：${fmt(job.done)} / ${fmt(job.total)} <button type="button" data-admin="seo-refresh">${t('刷新进度','Refresh')}</button></p>`:`<div class="actions"><button type="button" class="primary" data-admin="card-batch">${t('AI 批量补全缺失的牌义','AI-fill all missing card copy')}</button></div><p class="muted small">${t('每张牌调用一次模型，计入每日 AI 预算；预算用完会自动停止，已完成的会保留。','One model call per card, counted against the daily AI budget; it stops when the budget runs out and keeps what is done.')}${job.finished?` ${t('上次完成','Last run')}: ${fmt(job.done)}/${fmt(job.total)}`:''}${(job.errors||[]).length?` · ${esc(job.errors.join('; '))}`:''}</p>`}</div>
 ${suits.map(([k,zh,en])=>`<details class="panel card-group"><summary><b>${t(zh,en)}</b> <span class="muted">${x.cards.filter(c=>c.suit===k&&c.has_zh).length}/${x.cards.filter(c=>c.suit===k).length}</span></summary><ul class="card-rows" role="list">${x.cards.filter(c=>c.suit===k).map(c=>`<li><span>${esc(c.zh)} · ${esc(c.en)}</span><span class="chips">${c.has_zh?'<span class="tag ok">中</span>':'<span class="tag">中 ✗</span>'}${c.has_en?'<span class="tag ok">EN</span>':'<span class="tag">EN ✗</span>'}${c.ai?`<span class="tag warn">${t('AI 待审','AI draft')}</span>`:''}</span><button type="button" data-admin="card-edit" data-slug="${esc(c.slug)}">${t('编辑','Edit')}</button></li>`).join('')}</ul></details>`).join('')}
 <div id="card-editor"></div>`;
 applyBars(e)}
function cardEditor(slug){const c=seoData.cards.find(x=>x.slug===slug),box=document.getElementById('card-editor');if(!c||!box)return;
 box.innerHTML=`<section class="panel card-edit"><div class="section-head"><h2 class="h3">${esc(c.zh)} · ${esc(c.en)}</h2><a href="/learn/${esc(c.slug)}" target="_blank" rel="noopener">${t('查看页面','View page')} ↗</a></div>${c.ai?`<div class="note">${t('这是 AI 草稿：请核对内容、改成你的语气后保存（保存即视为已审核）。','This is an AI draft: check it, adjust the voice, then save (saving marks it reviewed).')}</div>`:''}<form data-admin-form="seo-card" data-slug="${esc(c.slug)}"><div class="two"><div>${counted('intro_zh',t('中文介绍（每段换行）','Chinese introduction (one paragraph per line)'),c.intro_zh,'',1500,true)}${counted('title_zh',t('中文标题（留空用默认）','Chinese title (blank = default)'),c.title_zh,'',32)}${counted('desc_zh',t('中文描述（留空用默认）','Chinese description'),c.desc_zh,'',120,true)}</div><div>${counted('intro_en','English introduction',c.intro_en,'',2500,true)}${field('theme_en','English theme',c.theme_en)}${field('upright_en','Upright keywords (EN)',c.upright_en)}${field('reversed_en','Reversed keywords (EN)',c.reversed_en)}${counted('title_en','English title',c.title_en,'',65)}${counted('desc_en','English description',c.desc_en,'',160,true)}</div></div><div class="actions"><button class="primary">${t('保存（已审核）','Save (reviewed)')}</button><button type="button" data-admin="card-ai" data-slug="${esc(c.slug)}">${t('用 AI 重写','Rewrite with AI')}</button></div></form></section>`;
 box.scrollIntoView({behavior:'smooth',block:'start'})}
// ---------- marketing console ----------
const TRIGGERS={manual:['手动生成','Manual'],'case-published':['自动 · 案例发布','Auto · example published'],'daily-card':['自动 · 每日一牌','Auto · card of the day']};
function draftText(d){return [d.title,d.text,(d.hashtags||[]).map(x=>'#'+x).join(' '),d.link].filter(Boolean).join('\n\n')}
function draftCard(d){const p=mktData.platforms[d.platform]||{zh:d.platform,en:d.platform};return `<article class="panel draft${d.status==='posted'?' posted':''}" data-draft="${esc(d.id.split(':')[1])}"><div class="draft-head"><span class="badge">${esc(t(p.zh,p.en))}</span><span class="muted small">${esc(t(...(TRIGGERS[d.trigger]||[d.trigger,d.trigger])))} · ${esc((d.created||'').slice(0,16).replace('T',' '))}</span>${d.status==='posted'?`<span class="tag ok">${t('已发布','Posted')}</span>`:''}</div>${d.title?`<h3>${esc(d.title)}</h3>`:''}<p class="draft-text">${esc(d.text)}</p>${(d.hashtags||[]).length?`<p class="tags-line">${d.hashtags.map(x=>'#'+esc(x)).join(' ')}</p>`:''}<p class="small"><a href="${esc(d.link)}" target="_blank" rel="noopener">${esc(d.link)}</a></p>${d.image_idea?`<p class="muted small">${t('配图建议：','Image idea: ')}${esc(d.image_idea)}</p>`:''}${pubBlock(d)}<div class="actions"><button type="button" class="primary" data-admin="draft-copy" data-id="${esc(d.id)}">${t('复制全文','Copy post')}</button><button type="button" data-admin="draft-status" data-id="${esc(d.id)}" data-status="${d.status==='posted'?'draft':'posted'}">${d.status==='posted'?t('改回草稿','Back to draft'):t('标记已发布','Mark posted')}</button><button type="button" class="danger" data-admin="draft-delete" data-id="${esc(d.id)}">${t('删除','Delete')}</button></div></article>`}
async function marketingTab(e){stopLogin();[mktData,pubData]=await Promise.all([api('/admin/marketing'),api('/admin/publish').catch(()=>null)]);const m=mktData,c=m.config,plats=Object.entries(m.platforms);
 const platBoxes=(name,sel)=>`<div class="chip-checks">${plats.map(([k,p])=>`<label><input type="checkbox" name="${name}" value="${k}" ${sel.includes(k)?'checked':''}>${esc(t(p.zh,p.en))}</label>`).join('')}</div>`;
 const pageOpts=Object.entries(m.pages).map(([k,p])=>`<option value="${esc(p)}">${esc(p)}</option>`).join('');
 e.innerHTML=`<div class="note">${t('用已配置的 AI 模型为各平台写草稿，附带可追踪的推广链接。小红书、微信视频号、TikTok 的草稿可以加图后定时自动发布（见下方“自动发帖”）；其他平台复制后手动发布。生成会计入每日 AI 预算。','Drafts for each platform written by your configured model, with trackable links. Xiaohongshu, WeChat Channels and TikTok drafts can be scheduled and posted automatically once they have a picture (see "Automatic posting"); copy the others and post them yourself. Generation counts against the daily AI budget.')}</div><div id="pub-area">${pubSection()}</div>
 <section class="panel"><h2 class="h3">${t('生成社媒文案','Write social posts')}</h2><form data-admin-form="mkt-generate" id="mkt-generate"><label for="mkt-source">${t('素材','Based on')}</label><select id="mkt-source" name="source"><option value="case">${t('已发布的算牌案例','A published example')}</option><option value="card">${t('一张牌（今日一牌）','A card (card of the day)')}</option><option value="topic">${t('自定义主题','A topic')}</option></select>
 <div data-src="case"><label for="mkt-case">${t('案例','Example')}</label>${m.cases.length?`<select id="mkt-case" name="case">${m.cases.map(x=>`<option value="${esc(x.slug)}">${esc(x.published)} · ${esc(x.question)}</option>`).join('')}</select>`:`<p class="muted">${t('还没有已发布的案例。','No published examples yet.')}</p>`}</div>
 <div data-src="card" hidden><label for="mkt-card">${t('牌','Card')}</label><select id="mkt-card" name="card">${m.cards.map(x=>`<option value="${esc(x.slug)}">${esc(x.zh)} · ${esc(x.en)}</option>`).join('')}</select></div>
 <div data-src="topic" hidden>${field('topic',t('主题（如：水逆期间如何沟通、新月许愿、塔罗入门）','Topic (e.g. communicating during Mercury retrograde, new-moon intentions, tarot for beginners)'))}</div>
 <label>${t('平台','Platforms')}</label>${platBoxes('platforms',c.platforms)}${field('note',t('补充要求（可选，如：强调首次免费、语气更轻松）','Extra instructions (optional)'))}<button class="primary">${t('生成草稿','Generate drafts')}</button></form></section>
 <h2 class="section-head">${t('文案草稿','Drafts')} <span class="muted small">${fmt(m.drafts.filter(d=>d.status!=='posted').length)} ${t('条待发布','to post')}</span></h2><div id="mkt-drafts" class="drafts">${m.drafts.map(draftCard).join('')||`<div class="empty">${t('还没有草稿。','No drafts yet.')}</div>`}</div>
 <div class="dash-grid"><section class="panel"><h2 class="h3">${t('自动化','Automation')}</h2><form data-admin-form="mkt-config">${check('auto_case',t('案例发布后，自动为下方平台生成文案草稿','Draft posts automatically when an example is published'),c.auto_case)}${check('daily',t('每天自动生成“今日一牌”文案草稿','Draft a card-of-the-day post every day'),c.daily)}<label for="daily_hour">${t('每日生成时间（工作室时区）','Daily time (studio time zone)')}</label><select id="daily_hour" name="daily_hour">${Array.from({length:24},(_,h)=>`<option value="${h}" ${h===c.daily_hour?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select><label>${t('默认平台','Default platforms')}</label>${platBoxes('platforms',c.platforms)}<label for="voice">${t('品牌语气（可选）','Brand voice (optional)')}</label><textarea id="voice" name="voice" maxlength="500" placeholder="${t('例如：温柔、克制、像朋友聊天；少用感叹号；称呼读者为“你”。','e.g. gentle, grounded, like a friend; few exclamation marks.')}">${esc(c.voice||'')}</textarea><button class="primary">${t('保存','Save')}</button></form></section>
 <section class="panel"><h2 class="h3">${t('推广链接（UTM）','Campaign links (UTM)')}</h2><p class="muted small">${t('每个平台、每次活动用不同的链接，“数据看板 → 渠道效果”就能看出哪条帖子带来了访客和注册。','Use a separate link per platform and campaign; Analytics → Channel performance then shows which post brought visitors and sign-ups.')}</p><form data-admin-form="mkt-link"><label for="l-channel">${t('渠道','Channel')}</label><select id="l-channel" name="channel">${m.channels.map(k=>`<option value="${k}">${esc(m.platforms[k]?t(m.platforms[k].zh,m.platforms[k].en):k)}</option>`).join('')}</select>${field('campaign',t('活动名（英文/数字，如 oct_fullmoon）','Campaign name (e.g. oct_fullmoon)'))}<label for="l-path">${t('落地页','Landing page')}</label><select id="l-path" name="path">${pageOpts}</select>${field('note',t('备注（可选）','Note (optional)'))}<button class="primary">${t('生成链接','Create link')}</button></form>
 ${m.links.length?`<ul class="link-list" role="list">${m.links.map(l=>`<li><div><b>${esc(l.channel)}</b> · ${esc(l.campaign)}${l.note?` · <span class="muted">${esc(l.note)}</span>`:''}<br><code>${esc(l.url)}</code></div><div class="actions"><button type="button" data-admin="copy" data-text="${esc(l.url)}">${t('复制','Copy')}</button><button type="button" class="danger" data-admin="link-delete" data-id="${esc(l.id)}">${t('删除','Delete')}</button></div></li>`).join('')}</ul>`:''}</section></div>`;
 const f=document.getElementById('mkt-generate'),sync=()=>f.querySelectorAll('[data-src]').forEach(el=>el.hidden=el.dataset.src!==f.elements.source.value);f.elements.source.addEventListener('change',sync);sync()}
async function adminAction(b){const a=b.dataset.admin,e=document.getElementById('admin-content');
 if(a.startsWith('pub-')||a.startsWith('job-'))return pubAction(b,a);
 if(a==='range'){statsRange=+b.dataset.range;return statsTab(e)}
 if(a==='copy')return copyText(b.dataset.text);
 if(a==='indexnow'){const r=await api('/admin/seo/indexnow','POST',{});toast(t(`已提交 ${r.count} 个网址，结果稍后见推送记录`,`Submitted ${r.count} URLs; see recent pushes shortly`));return}
 if(a==='seo-refresh')return seoTab(e);
 if(a==='card-edit')return cardEditor(b.dataset.slug);
 if(a==='card-batch'){if(!confirm(t('将为缺少介绍的牌逐张调用 AI（计入每日预算）。继续？','Call the AI once per card that lacks copy (counts against the daily budget). Continue?')))return;const r=await api('/admin/seo/cards/batch','POST',{});toast(r.total?t(`已开始，共 ${r.total} 张，可稍后刷新查看进度`,`Started ${r.total} cards; refresh later for progress`):t('所有牌都已有介绍','Every card already has copy'));return seoTab(e)}
 if(a==='card-ai'){b.disabled=true;toast(t('AI 正在写，约需 10–30 秒…','Writing… about 10–30 seconds'));const r=await api(`/admin/seo/cards/${b.dataset.slug}/ai`,'POST',{overwrite:true});const c=seoData.cards.find(x=>x.slug===b.dataset.slug);Object.assign(c,r.card,{ai:true,has_zh:!!r.card.intro_zh,has_en:!!r.card.intro_en});cardEditor(b.dataset.slug);toast(t('已生成草稿，请审核后保存','Draft ready; review and save'));return}
 const draft=id=>mktData.drafts.find(x=>x.id===id);
 if(a==='draft-copy')return copyText(draftText(draft(b.dataset.id)),t('已复制，可以去发布了','Copied — ready to post'));
 if(a==='draft-status'){const r=await api('/admin/marketing/drafts/'+b.dataset.id.split(':')[1],'PUT',{status:b.dataset.status});Object.assign(draft(b.dataset.id),r.draft);b.closest('.draft').outerHTML=draftCard(r.draft);return}
 if(a==='draft-delete'){if(!confirm(t('删除这条草稿？','Delete this draft?')))return;await api('/admin/marketing/drafts/'+b.dataset.id.split(':')[1],'PUT',{action:'delete'});mktData.drafts=mktData.drafts.filter(x=>x.id!==b.dataset.id);b.closest('.draft').remove();return}
 if(a==='link-delete'){await api('/admin/marketing/links/'+b.dataset.id,'DELETE');return marketingTab(e)}}
async function adminSubmit(f){const kind=f.dataset.adminForm,e=document.getElementById('admin-content'),el=f.elements,val=k=>el[k]?.value??'';
 if(kind==='pub-config')return pubConfig(f);
 if(kind==='seo-config'){await api('/admin/seo','PUT',{verify:{google:val('v_google'),bing:val('v_bing'),baidu:val('v_baidu'),yandex:val('v_yandex')},og_image:val('og_image'),indexnow:el.indexnow.checked});toast(t('已保存','Saved'));return seoTab(e)}
 if(kind==='seo-page'){const k=f.dataset.key;await api('/admin/seo','PUT',{pages:{[k]:{zh_title:val(k+'_zh_title'),zh_desc:val(k+'_zh_desc'),en_title:val(k+'_en_title'),en_desc:val(k+'_en_desc')}}});toast(t('已保存','Saved'));return seoTab(e)}
 if(kind==='seo-card'){const slug=f.dataset.slug,card={slug,reviewed:true};['intro_zh','intro_en','theme_en','upright_en','reversed_en','title_zh','desc_zh','title_en','desc_en'].forEach(k=>card[k]=val(k));await api('/admin/seo','PUT',{card});toast(t('已保存，页面已更新','Saved; the page is updated'));await seoTab(e);return cardEditor(slug)}
 if(kind==='mkt-generate'){const source=val('source'),ref=source==='case'?val('case'):source==='card'?val('card'):val('topic'),platforms=[...f.querySelectorAll('input[name=platforms]:checked')].map(x=>x.value);toast(t('AI 正在写，约需 10–40 秒…','Writing… about 10–40 seconds'));const r=await api('/admin/marketing/generate','POST',{source,ref,platforms,note:val('note')});mktData.drafts=[...r.drafts,...mktData.drafts];const box=document.getElementById('mkt-drafts');box.querySelector('.empty')?.remove();box.insertAdjacentHTML('afterbegin',r.drafts.map(draftCard).join(''));box.scrollIntoView({behavior:'smooth',block:'start'});toast(t(`已生成 ${r.drafts.length} 条草稿`,`${r.drafts.length} drafts ready`));return}
 if(kind==='mkt-config'){await api('/admin/marketing','PUT',{auto_case:el.auto_case.checked,daily:el.daily.checked,daily_hour:+val('daily_hour'),platforms:[...f.querySelectorAll('input[name=platforms]:checked')].map(x=>x.value),voice:val('voice')});toast(t('已保存','Saved'));return}
 if(kind==='mkt-link'){const r=await api('/admin/marketing/links','POST',{channel:val('channel'),campaign:val('campaign'),path:val('path'),note:val('note')});await copyText(r.link.url,t('链接已生成并复制','Link created and copied'));return marketingTab(e)}}
// ================= v0.8.1 scheduled posting (小红书 / 视频号 / TikTok) =================
let pubData=null,loginTimer=null;
const PUB_ST={scheduled:['已排期','Scheduled',''],running:['发布中','Posting',''],published:['已发布','Posted','ok'],manual:['待手动发布','Post by hand','warn'],failed:['失败','Failed','bad'],cancelled:['已取消','Cancelled',''],tested:['试运行完成','Test done','ok']};
const ACC_ST={ok:['已登录','Logged in','ok'],expired:['登录已失效','Login expired','bad'],risk:['风控冷却中','Risk cooldown','bad'],logged_out:['未登录','Not logged in','warn'],unknown:['未登录','Not logged in','warn']};
const REASONS={mode:['手动模式：到点提醒','Manual mode reminder'],login:['未登录或登录失效','Not logged in'],risk:['平台风控/验证','Platform verification'],media:['配图或视频不可用','Media problem'],error:['自动发布多次失败','Automatic posting failed']};
const when=iso=>iso?new Date(iso).toLocaleString(lang==='zh'?'zh-CN':'en-GB',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',weekday:'short'}):'';
const pubName=p=>{const x=pubData?.platforms?.[p]||mktData?.platforms?.[p];return x?t(x.zh,x.en):p};
const stTag=(map,k)=>{const s=map[k]||[k,k,''];return `<span class="tag ${s[2]}">${esc(t(s[0],s[1]))}</span>`};
function mediaThumbs(list,did){return list?.length?`<div class="media-row">${list.map(x=>`<figure class="media-item">${x.kind==='video'?`<a class="media-video" href="${esc(x.url)}" target="_blank" rel="noopener">▶ ${esc(x.name||t('视频','Video'))}</a>`:`<a href="${esc(x.url)}" target="_blank" rel="noopener"><img src="${esc(x.url)}" alt="${esc(x.name||'')}" loading="lazy"></a>`}${did?`<button type="button" class="media-del" data-admin="pub-media-del" data-id="${esc(did)}" data-media="${esc(x.id)}" aria-label="${t('移除','Remove')}">×</button>`:''}</figure>`).join('')}</div>`:''}
function pubBlock(d){if(!pubData||!pubData.platforms[d.platform])return '';const id=d.id.split(':')[1],p=pubData.platforms[d.platform],job=pubData.jobs.find(j=>j.draft===d.id&&['scheduled','running','manual'].includes(j.status)&&!j.dry_run);
 const needs=p.needs==='video'?t('需要视频；只放图片时会自动做成竖版短视频','Needs a video; pictures become a vertical slideshow'):t('图文或视频','Pictures or a video');
 return `<div class="pub-box">${mediaThumbs((d.media||[]).map(x=>({...x,url:x.url||'/api/admin/marketing/media/'+x.file.split('/').pop()})),d.id)}
 <label class="upload-btn"><input type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime,video/webm" multiple data-media-upload="${esc(id)}">${t('＋ 添加图片/视频','+ Add pictures/video')}</label><span class="muted small">${esc(needs)}</span>
 ${job?`<p class="pub-state">${stTag(PUB_ST,job.status)} ${esc(when(job.run_at))} · ${esc(job.status==='manual'?t('等你手动发布，见上方发布队列','waiting for you, see the queue above'):p.config.mode==='auto'?t('到点自动发布','posts automatically'):t('到点提醒你手动发','you get a reminder'))}</p>`:
 `<div class="pub-sched"><select data-when="${esc(id)}" aria-label="${t('发布时间','When')}"><option value="slot">${t('下一个空闲时段','Next free slot')}</option><option value="at">${t('指定时间','Pick a time')}</option><option value="now">${t('立即','Now')}</option></select><input type="datetime-local" data-at="${esc(id)}" hidden aria-label="${t('时间','Time')}">
 <button type="button" class="primary" data-admin="pub-schedule" data-id="${esc(id)}">${t('定时发布','Schedule')}</button><button type="button" data-admin="pub-test" data-id="${esc(id)}" title="${t('打开创作者后台填好内容并截图，不点发布','Fills the post and takes a screenshot without publishing')}">${t('试运行','Test run')}</button></div>`}</div>`}
function accountCard(k,p){const a=p.account,c=p.config,cool=a.status==='risk'&&a.paused_until?` · ${t('至','until')} ${esc(when(a.paused_until))}`:'';
 return `<section class="panel pub-account" data-p="${k}"><div class="draft-head"><h3>${esc(t(p.zh,p.en))}</h3>${stTag(ACC_ST,a.status)}<span class="muted small">${a.checked?t('检测于 ','checked ')+esc(when(a.checked)):''}${cool}</span></div>${a.note?`<p class="muted small">${esc(a.note)}</p>`:''}
 <div class="actions"><button type="button" class="primary" data-admin="pub-login" data-p="${k}">${t('扫码登录','Log in by QR')}</button><button type="button" data-admin="pub-check" data-p="${k}">${t('检测登录','Check login')}</button>${a.status==='ok'?`<button type="button" class="danger" data-admin="pub-logout" data-p="${k}">${t('退出','Log out')}</button>`:''}</div>
 <div class="qr-box" data-qr="${k}" hidden></div>
 <details><summary>${t('发帖设置','Posting settings')} · ${esc(t({auto:'自动发布',manual:'到点提醒',off:'已关闭'}[c.mode],{auto:'Automatic',manual:'Reminder',off:'Off'}[c.mode]))} · ${esc(c.slots.join(' / '))}</summary><form data-admin-form="pub-config" data-p="${k}">
 <label for="mode-${k}">${t('发布方式','Mode')}</label><select id="mode-${k}" name="mode">${[['auto','自动发布（失败或风控时改为提醒）','Automatic (falls back to a reminder)'],['manual','到点提醒，我手动发','Remind me to post by hand'],['off','关闭','Off']].map(([v,z,e])=>`<option value="${v}" ${c.mode===v?'selected':''}>${t(z,e)}</option>`).join('')}</select>
 <label for="slots-${k}">${t('发帖时段（工作室时区 ','Posting times (studio time zone ')}${esc(pubData.tz)}）</label><input id="slots-${k}" name="slots" value="${esc(c.slots.join(','))}" placeholder="12:30,20:30">
 ${check('auto_queue',t('新生成的草稿（有图时）自动排进下一个时段','Queue new drafts (with media) into the next slot automatically'),c.auto_queue)}
 <div class="two"><div><label for="gap-${k}">${t('两帖最短间隔（分钟）','Minimum gap (minutes)')}</label><input id="gap-${k}" name="min_gap" type="number" min="10" max="1440" value="${c.min_gap}"></div><div><label for="cap-${k}">${t('24 小时内最多','Max per 24 h')}</label><input id="cap-${k}" name="daily_cap" type="number" min="1" max="10" value="${c.daily_cap}"></div></div>
 <button class="primary">${t('保存','Save')}</button></form></details></section>`}
function jobCard(j){const reason=REASONS[j.reason],media=mediaThumbs(j.media);let acts='';
 if(j.status==='scheduled')acts=`<button type="button" data-admin="job-now" data-id="${j.id}">${t('立即发布','Post now')}</button><button type="button" class="danger" data-admin="job-cancel" data-id="${j.id}">${t('取消','Cancel')}</button>`;
 if(j.status==='manual')acts=`<button type="button" class="primary" data-admin="job-copy" data-id="${j.id}">${t('复制文案','Copy text')}</button><button type="button" data-admin="job-posted" data-id="${j.id}">${t('我已发布','I posted it')}</button><button type="button" data-admin="job-retry" data-id="${j.id}">${t('重试自动发布','Retry automatically')}</button><button type="button" class="danger" data-admin="job-cancel" data-id="${j.id}">${t('取消','Cancel')}</button>`;
 if(['failed','cancelled'].includes(j.status)&&!j.dry_run)acts=`<button type="button" data-admin="job-retry" data-id="${j.id}">${t('重新排队','Queue again')}</button>`;
 if(['failed','cancelled','tested','published'].includes(j.status))acts+=`<button type="button" class="danger" data-admin="job-delete" data-id="${j.id}">${t('删除记录','Delete')}</button>`;
 return `<li class="job job-${j.status}"><div class="draft-head"><span class="badge">${esc(pubName(j.platform))}</span>${stTag(PUB_ST,j.status)}${j.dry_run?`<span class="tag">${t('试运行','Test')}</span>`:''}<span class="muted small">${esc(when(j.status==='published'?j.updated:j.run_at))}</span></div>
 <p class="job-title">${esc((j.title||j.text.split('\n')[0]).slice(0,80))}</p>${reason&&j.status==='manual'?`<p class="small warn-text">${esc(t(...reason))}</p>`:''}${j.error&&j.status!=='published'?`<p class="muted small">${esc(j.error)}</p>`:''}
 ${j.status==='manual'?`<details><summary>${t('查看文案与配图','Text and media')}</summary><p class="draft-text">${esc(j.kit)}</p>${media}<p class="muted small">${t('手机上长按图片可保存到相册。','On a phone, long-press a picture to save it.')}</p></details>`:''}
 <p class="small">${j.url&&j.status==='published'?`<a href="${esc(j.url)}" target="_blank" rel="noopener">${t('查看帖子','Open post')}</a> · `:''}${j.shot?`<a href="/api/admin/publish/shot/${esc(j.shot)}" target="_blank" rel="noopener">${t('截图','Screenshot')}</a>`:''}</p>
 ${acts?`<div class="actions">${acts}</div>`:''}</li>`}
function pubSection(){if(!pubData)return `<section class="panel"><h2 class="h3">${t('自动发帖','Automatic posting')}</h2><p class="muted">${t('发帖服务状态读取失败，请刷新。','Could not load posting status; refresh.')}</p></section>`;
 const w=pubData.worker,jobs=pubData.jobs,todo=jobs.filter(j=>j.status==='manual').length;
 return `<h2 class="section-head" id="pub-top">${t('自动发帖','Automatic posting')} <span class="muted small">${t('小红书 · 微信视频号 · TikTok','Xiaohongshu · WeChat Channels · TikTok')}</span></h2>
 <div class="note">${w.online?t('发帖服务运行中。','Posting service is running. '):`<b class="warn-text">${t('发帖服务未运行','Posting service is offline')}</b> — ${t('在服务器执行 docker compose up -d publisher。','run docker compose up -d publisher on the server. ')}`}${t('三个平台都没有开放发帖接口，系统用服务器上的浏览器模拟人工操作：先扫码登录一次；到点自动发布，遇到登录失效、平台验证或连续失败会自动改为邮件提醒你手动发。建议第一次先点草稿上的“试运行”，确认能正确填好内容。自动化操作存在被平台限流的风险，请保持每天少量发帖。','None of these platforms has a posting API, so a browser on the server does what you would do by hand. Log in by QR once; posts go out on schedule, and when a login expires, the platform asks for verification or posting keeps failing, you get an email to post by hand. Try a "Test run" first. Automation can get accounts rate-limited, so keep the volume low.')}</div>
 <div class="pub-accounts">${['xiaohongshu','channels','tiktok'].filter(k=>pubData.platforms[k]).map(k=>accountCard(k,pubData.platforms[k])).join('')}</div>
 <h2 class="section-head">${t('发布队列','Posting queue')} <span class="muted small">${todo?`<b class="warn-text">${todo} ${t('条待你手动发布','to post by hand')}</b>`:''}</span><button type="button" class="small-btn" data-admin="pub-refresh">${t('刷新','Refresh')}</button></h2>
 ${jobs.length?`<ul class="jobs" role="list">${[...jobs.filter(j=>j.status==='manual'),...jobs.filter(j=>j.status!=='manual')].map(jobCard).join('')}</ul>`:`<div class="empty">${t('还没有排期的帖子。在下方草稿上添加图片后点“定时发布”。','Nothing scheduled yet. Add a picture to a draft below and press "Schedule".')}</div>`}`}
async function pubReload(){pubData=await api('/admin/publish');const box=document.getElementById('pub-area');if(box)box.innerHTML=pubSection();document.querySelectorAll('#mkt-drafts .draft').forEach(el=>{const d=mktData.drafts.find(x=>x.id==='mkt:'+el.dataset.draft);if(d)el.outerHTML=draftCard(d)})}
function stopLogin(){clearInterval(loginTimer);loginTimer=null}
function showQR(k,r){const box=document.querySelector(`[data-qr="${k}"]`);if(!box)return;box.hidden=false;
 if(r.status==='waiting')box.innerHTML=`<img src="data:image/png;base64,${r.qr}" alt="${t('登录二维码','Login QR code')}"><p class="small">${t(`用${pubName(k)} App 扫码并确认登录`,`Scan with the ${pubName(k)} app and confirm`)}${r.left?` · ${r.left}s`:''}</p><button type="button" data-admin="pub-login-cancel" data-p="${k}">${t('取消','Cancel')}</button>`;
 else if(r.status==='ok'){box.innerHTML=`<p class="tag ok">${t('登录成功','Logged in')}</p>`;stopLogin();toast(t('登录成功，已保存','Logged in and saved'));setTimeout(pubReload,800)}
 else{box.innerHTML=`<p class="small warn-text">${esc(r.message||t('二维码已过期，请重新扫码登录','QR code expired; try again'))}</p>`;stopLogin()}}
async function uploadMedia(id,file){const r=await fetch(`/api/admin/marketing/drafts/${id}/media`,{method:'POST',headers:{'X-CSRF':state?.csrf||'','X-Filename':encodeURIComponent(file.name),'Content-Type':file.type||'application/octet-stream'},body:file});let j={};try{j=await r.json()}catch(e){}if(!r.ok)throw Error(j.error||(r.status===413?t('文件过大（图片 20MB、视频 500MB 以内）','File too large (20 MB pictures, 500 MB video)'):t('上传失败','Upload failed')));return j.draft}
document.addEventListener('change',async e=>{const el=e.target;
 if(el.dataset.when){const at=document.querySelector(`[data-at="${el.dataset.when}"]`);if(at)at.hidden=el.value!=='at';return}
 if(!el.dataset.mediaUpload||!el.files?.length)return;const id=el.dataset.mediaUpload;el.disabled=true;
 try{let d;for(const f of el.files){toast(t(`正在上传 ${f.name}…`,`Uploading ${f.name}…`));d=await uploadMedia(id,f)}const i=mktData.drafts.findIndex(x=>x.id===d.id);mktData.drafts[i]=d;document.querySelector(`[data-draft="${id}"]`).outerHTML=draftCard(d);toast(t('已添加','Added'))}catch(err){toast(err.message);el.disabled=false}});
async function pubAction(b,a){const e=document.getElementById('admin-content'),k=b.dataset.p,id=b.dataset.id;b.disabled=true;
 if(a==='pub-refresh'){await pubReload();return toast(t('已刷新','Refreshed'))}
 if(a==='pub-login'){stopLogin();toast(t('正在打开登录页，约 10 秒…','Opening the login page, about 10 seconds…'));const r=await api(`/admin/publish/${k}/login`,'POST',{});showQR(k,r);if(r.status==='waiting')loginTimer=setInterval(async()=>{try{showQR(k,await api(`/admin/publish/${k}/login`))}catch(err){stopLogin();toast(err.message)}},2500);return}
 if(a==='pub-login-cancel'){stopLogin();await api(`/admin/publish/${k}/login`,'DELETE');const box=document.querySelector(`[data-qr="${k}"]`);if(box){box.hidden=true;box.innerHTML=''}return}
 if(a==='pub-check'){toast(t('正在检测，约 10–20 秒…','Checking, about 10–20 seconds…'));const r=await api(`/admin/publish/${k}/check`,'POST',{});toast(r.status==='ok'?t('登录有效','Login is valid'):r.status==='busy'?t('正在发帖，请稍后再试','Posting in progress; try later'):t('登录已失效，请扫码','Login expired; scan the QR code'));return pubReload()}
 if(a==='pub-logout'){if(!confirm(t('退出后需要重新扫码才能自动发帖。继续？','You will need to scan again to post automatically. Continue?')))return;await api(`/admin/publish/${k}/logout`,'POST',{});return pubReload()}
 if(a==='pub-media-del'){const d=mktData.drafts.find(x=>x.id===id),r=await api('/admin/marketing/drafts/'+id.split(':')[1],'PUT',{media:(d.media||[]).filter(x=>x.id!==b.dataset.media).map(x=>x.id)});Object.assign(d,r.draft);document.querySelector(`[data-draft="${id.split(':')[1]}"]`).outerHTML=draftCard(d);return}
 if(a==='pub-schedule'||a==='pub-test'){const sel=document.querySelector(`[data-when="${id}"]`),at=document.querySelector(`[data-at="${id}"]`),w=a==='pub-test'?'now':sel.value;
  if(w==='at'&&!at.value)return toast(t('请选择时间','Pick a time'));
  const r=await api(`/admin/marketing/drafts/${id}/schedule`,'POST',{when:w,at:w==='at'?new Date(at.value).toISOString():undefined,dry_run:a==='pub-test'});
  toast(a==='pub-test'?t('已开始试运行，约 1–3 分钟后在发布队列查看截图','Test started; check the queue for a screenshot in 1–3 minutes'):t(`已排期：${when(r.job.run_at)}`,`Scheduled for ${when(r.job.run_at)}`));await pubReload();return}
 const j=pubData.jobs.find(x=>x.id===id);
 if(a==='job-copy')return copyText(j.kit,t('文案已复制，去 App 里粘贴发布吧','Copied — paste it in the app'));
 if(a==='job-posted'){const url=prompt(t('已在 App 里发布了？可以粘贴帖子链接（可留空）：','Posted in the app? Paste the post link (optional):'),'');if(url===null)return;await api(`/admin/publish/jobs/${id}`,'POST',{action:'posted',url:url.trim()});toast(t('已记录为已发布','Marked as posted'));await marketingTab(e);document.getElementById('pub-top')?.scrollIntoView({block:'start'});return}
 if(a==='job-cancel'&&!confirm(t('取消这条排期？','Cancel this scheduled post?')))return;
 if(a==='job-delete'){await api(`/admin/publish/jobs/${id}`,'POST',{action:'delete'});return pubReload()}
 await api(`/admin/publish/jobs/${id}`,'POST',{action:a.slice(4)});toast(t('已更新','Updated'));return pubReload()}
async function pubConfig(f){const el=f.elements,k=f.dataset.p;await api('/admin/publish/'+k,'PUT',{mode:el.mode.value,slots:el.slots.value,auto_queue:el.auto_queue.checked,min_gap:+el.min_gap.value,daily_cap:+el.daily_cap.value});toast(t('已保存','Saved'));return pubReload()}
document.addEventListener('input',ev=>{const x=ev.target;if(!x.matches?.('[data-count]'))return;const c=document.querySelector(`[data-count-for="${x.id}"]`);if(c){c.textContent=`${x.value.length} / ${c.dataset.max}`;c.classList.toggle('over',x.value.length>+c.dataset.max)}});
